UPDATE `job_queue` SET `status` = 'failed', `lastError` = 'The series:generation job type is retired: series are derived and described by the series projection', `lastErrorPublic` = '{"code":"no_handler","message":"No handler is available for this capability"}', `completedAt` = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER), `runtimeUpdatedAt` = CAST((julianday('now') - 2440587.5) * 86400000 AS INTEGER) WHERE `type` = 'series:generation' AND `status` IN ('pending', 'processing') AND `attemptId` IS NULL AND `workerSlotId` IS NULL AND `workerSessionId` IS NULL AND `leaseExpiresAt` IS NULL;
